use superba_core::Locale;

const LOCALE_EN: &str = include_str!("../locales/en.toml");
const LOCALE_ZH_CN: &str = include_str!("../locales/zh-CN.toml");

/// UI strings of this crate (`catalog.*` keys) for `locale`, to layer onto a
/// [`superba_core::Catalog`] with `add_toml`.
pub fn i18n_source(locale: Locale) -> &'static str {
    match locale {
        Locale::En => LOCALE_EN,
        Locale::ZhCn => LOCALE_ZH_CN,
    }
}
